// Passos 1 e 2: função apresentar, com os parâmetros nome e idade.
function apresentar(nome, idade) {
  // Passo 3: conferimos as entradas antes de montar a frase.
  if (typeof nome !== 'string' || typeof idade !== 'number') {
    throw new Error('nome precisa ser texto e idade precisa ser número');
  }

  // Passo 4: montamos a frase com crases e devolvemos.
  return `${nome} tem ${idade} anos.`;
}

// Passo 5: usamos a função e imprimimos o que ela devolveu.
const frase = apresentar('Maria', 25);
console.log(frase); // imprime: Maria tem 25 anos.
